static int mlx5e_handle_feature ( struct net_device * netdev , netdev_features_t * features , netdev_features_t feature , mlx5e_feature_handler feature_handler ) { netdev_features_t changes = * features ^ netdev -> features ; bool enable = ! ! ( * features & feature ) ; int err ; err = feature_handler ( netdev , enable ) ; if ( err ) { MLX5E_SET_FEATURE ( features , feature , ! enable ) ; netdev_err ( netdev , "%s feature %pNF failed, err %d\n" , enable ?"Enable" : "Disable" , & feature , err ) ; return err ; } return 0 ; } 